mapper.select:
SELECT 
  FROM sys50_specific_menu
       INNER JOIN sys06_menu ON sys50_menu_id = sys06_menu_id
 WHERE sys50_company_id = #{companyId}
   AND sys50_specific_work_cd LIKE #{specificWorkCd}
 ORDER BY sys50_specific_work_cd, sys50_menu_id

mapper.update:
UPDATE sys50_specific_menu
   SET sys50_specific_work_cd = #{req.specificWorkCd},
       sys50_menu_id          = #{req.menuId},
       sys50_note             = #{req.note}
 WHERE sys50_specific_menu_id = #{req.specificMenuId}
   AND sys50_company_id       = #{companyId}

mapper.delete:
DELETE FROM sys50_specific_menu
 WHERE sys50_company_id = #{companyId}
   AND sys50_specific_menu_id IN
#{id}
